sys_variable_value.value:
(function execute(inputs, outputs) {

    var yr = parseInt(inputs.string_yr);
    var next_yr = yr + 1;
    var str_next_yr_start = next_yr.toString() + "-01-01 00:00:00";
    var next_yr_start = new GlideDateTime(str_next_yr_start);
    var yearStart = next_yr_start.getYearLocalTime();

    inputs.staging_records.next();

    if (inputs.num_staging_records < 54 || inputs.staging_records.getValue('sys_created_on') < next_yr_start) { //or created before end of the year

        var strComplaintType = '5227b08f2f4b60d04cbeb1e72799b659'; //HR Service for Internal Complaints
        var strRefusalType = 'b745a0501b53ac10ea0eda02dd4bcb4b'; //HR Service for Refusal To WOrk
        var strInspectType = 'a94b0c891b7e7c109fde86acdd4bcbc1'; //HR Service for Inspections
        var strCorrectiveType = 'a284e0261b7a30109fde86acdd4bcbfc'; //HR Service for Corrective Action
        var strInvestigationType = '6a2b1ada2f4f2c904cbeb1e72799b6ae,5227b08f2f4b60d04cbeb1e72799b659,b745a0501b53ac10ea0eda02dd4bcb4b'; //HR Service for Workplace Incident Report
        var strIncident = '6a2b1ada2f4f2c904cbeb1e72799b6ae';

        var strStateOpen = '903,18,103,807,1,109,10,101,30,102,104,201,203,204,301,302,400,206,113,900,901,904,905,906,908';
        var strStateClosed = '111,105,3,4,7,200,205,110,112,902,907';

        var loc;
        var grBuilding = new GlideRecord('cmn_location');
        grBuilding.addEncodedQuery('typeLIKEefe3ed571be74c50028598aebd4bcb34'); //Query where type contains BUilding.
        grBuilding.query();

        var dt = new GlideDateTime();
        var resObj = new HoCOHSMRepo();
        
        while (grBuilding.next()) {
            //var loc = '046d5f461b5afc1078230d47dc4bcbce';           //181 Queen used for testing instead of looping.
            loc = grBuilding.sys_id;

            var gr1058 = new GlideRecord('x_hccc_hoc_ohs_lab1058_staging_table');
            gr1058.initialize();
            gr1058.report_year = yr.toString();
            gr1058.building = loc;
            
            //Cases created/received
            gr1058.complaints_received = resObj.get1058_Type_CreatedByMonth(strComplaintType, 'inc_date_time', loc, 'inc_location', '', '', yearStart);
            gr1058.refusals_received = resObj.get1058_Type_CreatedByMonth(strRefusalType, 'inc_date_time', loc, 'inc_location', '', '', yearStart);

            gr1058.inspections = resObj.get1058_Type_CreatedByMonth(strInspectType, 'wi_date_time_of_inspection', loc, 'wi_building', '', '', yearStart);

            gr1058.hazards_identified = resObj.get1058_Type_CreatedByMonth(strCorrectiveType, 'opened_at', loc, 'wi_building', '', '', yearStart);

            gr1058.investigations = resObj.get1058_Type_CreatedByMonth(strInvestigationType, 'inc_date_time', loc, 'inc_location', '', '', yearStart);

            gr1058.disabling_injury = resObj.get1058_Type_CreatedByMonth(strIncident, 'date_and_time_of_occurrence', loc, 'inc_location', 'disab_injury', '', yearStart);

            gr1058.minor_injury = resObj.get1058_Type_CreatedByMonth(strIncident, 'date_and_time_of_occurrence', loc, 'inc_location', 'minor', '', yearStart);

            gr1058.time_lost = resObj.get1058_Type_CreatedByMonth(strIncident, 'date_and_time_of_occurrence', loc, 'inc_location', 'disab_injury', '', yearStart, 'sum');

            //Cases Unresolved
            gr1058.complaints_unresolved = resObj.get1058_Type_CreatedByMonth(strComplaintType, 'inc_date_time', loc, 'inc_location', '', strStateOpen, yearStart);
            gr1058.refusals_unresolved = resObj.get1058_Type_CreatedByMonth(strRefusalType, 'inc_date_time', loc, 'inc_location', '', strStateOpen, yearStart);
            //gr1058.hazards_unresolved = resObj.get1058_Type_CreatedByMonth(strCorrectiveType, 'wi_date_time_of_inspection', loc, 'wi_building', '', strStateOpen, yearStart);
            gr1058.hazards_unresolved = resObj.get1058_Type_UnresolvedByMonth(strCorrectiveType, 'opened_at', 'wi_completion_date', loc, 'wi_building', yearStart);
            
            //Cases resolved
            gr1058.complaints_resolved = resObj.get1058_Type_CreatedByMonth(strComplaintType, 'inc_date_time', loc, 'inc_location', '', strStateClosed, yearStart);
            gr1058.refusals_resolved = resObj.get1058_Type_CreatedByMonth(strRefusalType, 'inc_date_time', loc, 'inc_location', '', strStateClosed, yearStart);
            //gr1058.hazards_resolved = resObj.get1058_Type_CreatedByMonth(strCorrectiveType, 'wi_completion_date', loc, 'wi_building', '', strStateClosed, yearStart);
            gr1058.hazards_resolved = resObj.get1058_Type_ResolvedByMonth(strCorrectiveType, 'opened_at', 'wi_completion_date', loc, 'wi_building', '', yearStart)


            gr1058.insert();
        }
    }
})(inputs, outputs);

